import AppKit
import ImageIO

final class ClipboardAccess {
    private static let originType = NSPasteboard.PasteboardType("com.clipnest.origin")
    private static let imageTypes: [NSPasteboard.PasteboardType] = [
        .png,
        .tiff,
        NSPasteboard.PasteboardType("public.jpeg"),
        NSPasteboard.PasteboardType("public.heic")
    ]
    private static let ignoredTypes: [NSPasteboard.PasteboardType] = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type"
    ].map { NSPasteboard.PasteboardType(rawValue: $0) }

    let pasteboard: NSPasteboard
    let origin = UUID().uuidString
    // 策略与前台应用标识由主线程更新，后台收录和复制前收录通过锁安全读取。
    private let stateLock = NSLock()
    private var policy = CapturePolicy(ownBundleID: Bundle.main.bundleIdentifier)
    private var _handledSequence: Int?

    var handledSequence: Int? {
        get { stateLock.withLock { _handledSequence } }
        set { stateLock.withLock { _handledSequence = newValue } }
    }

    init(_ pasteboard: NSPasteboard = .general) { self.pasteboard = pasteboard }

    func updateFrontmostApplication(_ bundleID: String?) {
        stateLock.withLock { policy.updateFrontmost(bundleID) }
    }

    func updateCapturePolicy(paused: Bool, ignoredBundleIDs: Set<String>, frontmostBundleID: String? = nil) {
        let sequence = pasteboard.changeCount
        stateLock.withLock {
            policy.updatePolicy(paused: paused, ignoredBundleIDs: ignoredBundleIDs,
                                frontmostBundleID: frontmostBundleID, sequence: sequence)
        }
    }

    func observeSource(_ bundleID: String?, sequence: Int) {
        stateLock.withLock { policy.observeSource(bundleID, sequence: sequence) }
    }

    private func captureDecision(for sequence: Int) -> CapturePolicy.Decision {
        stateLock.withLock { policy.decision(for: sequence) }
    }

    private func readChange(allowRetrySleep: Bool) throws -> (sequence: Int, payload: Payload?, sourceApp: String?) {
        let attempts = allowRetrySleep ? 5 : 2
        for attempt in 0..<attempts {
            let before = pasteboard.changeCount
            let decision = captureDecision(for: before)
            if decision.skip { return (before, nil, nil) }
            let payload = try read()
            if before == pasteboard.changeCount {
                return (before, captureDecision(for: before).skip ? nil : payload, decision.sourceApp)
            }
            if allowRetrySleep && attempt < attempts - 1 { Thread.sleep(forTimeInterval: 0.05) }
        }
        throw AppError(L("剪贴板持续变化，未能获得完整记录。"), code: .clipboard)
    }

    @discardableResult
    func capture(in store: HistoryStore, allowRetrySleep: Bool = true) throws -> Bool {
        guard handledSequence != pasteboard.changeCount else { return false }
        let change = try readChange(allowRetrySleep: allowRetrySleep)
        if let payload = change.payload { _ = try store.save(payload, sourceApp: change.sourceApp) }
        handledSequence = change.sequence
        return change.payload != nil
    }

    func read() throws -> Payload? {
        guard SystemAccess.clipboardStatus(for: pasteboard) != .denied else {
            throw AppError(L("无法读取剪贴板"), code: .clipboard)
        }
        let types = Set(pasteboard.types ?? [])
        if Self.ignoredTypes.contains(where: { types.contains($0) }) || pasteboard.string(forType: Self.originType) == origin { return nil }
        if types.contains(.fileURL) {
            guard let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty else {
                throw AppError(L("无法读取剪贴板文件列表。"), code: .clipboard)
            }
            return .files(urls.map(\.path))
        }
        if types.contains(.string) {
            guard let text = pasteboard.string(forType: .string) else { throw AppError(L("无法读取剪贴板文本。"), code: .clipboard) }
            // 部分应用复制图片时会附带空字符串，空文本时继续检查图片格式。
            if !text.isEmpty {
                return .text(text, html: try optional(.html, types), rtf: try optional(.rtf, types))
            }
        }
        if let type = Self.imageTypes.first(where: { types.contains($0) }) {
            guard let data = try optional(type, types) else { throw AppError(L("无法读取剪贴板图片。"), code: .clipboard) }
            let source = try ClipImage.source(data)
            let (width, height) = try ClipImage.size(source)
            var png = data
            if type != .png {
                guard let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else {
                    throw AppError(type == .tiff ? L("无法解码 TIFF 图片。") : L("无法读取剪贴板图片。"), code: .clipboard)
                }
                png = try ClipImage.png(image)
            }
            return .image(png: png, width: width, height: height)
        }
        return nil
    }
    private func optional(_ type: NSPasteboard.PasteboardType, _ types: Set<NSPasteboard.PasteboardType>) throws -> Data? {
        guard types.contains(type) else { return nil }
        guard let data = pasteboard.data(forType: type) else { throw AppError(L("无法读取 %@ 格式。", type.rawValue), code: .clipboard) }
        guard data.count <= Limits.bytes else { throw AppError(L("剪贴板中的 %@ 数据超过 %ld MiB，未保存到历史。", type.rawValue, Limits.recordSizeMiB), code: .validation) }
        return data
    }
    @discardableResult
    func write(_ payload: Payload, preservingChangesIn store: HistoryStore? = nil) throws -> Int {
        try payload.validate()
        var objects: [NSPasteboardWriting] = []
        switch payload {
        case let .files(paths):
            for path in paths {
                _ = try FileManager.default.attributesOfItem(atPath: path)
                let item = NSPasteboardItem()
                guard item.setString(URL(fileURLWithPath: path).absoluteString, forType: .fileURL),
                      item.setString(origin, forType: Self.originType) else { throw AppError(L("无法创建文件剪贴板记录。")) }
                objects.append(item)
            }
        case let .text(text, html, rtf):
            objects = [try item(with: [(.string, Data(text.utf8)), (.html, html), (.rtf, rtf)])]
        case let .image(png, _, _):
            var formats: [(NSPasteboard.PasteboardType, Data?)] = [(.png, png)]
            if let tiff = NSImage(data: png)?.tiffRepresentation {
                formats.append((.tiff, tiff))
            }
            objects = [try item(with: formats)]
        }
        if let store {
            try capture(in: store)
            guard handledSequence == pasteboard.changeCount else {
                throw AppError(L("保存期间剪贴板已更新，请重新选择要复制的记录。"))
            }
        }
        pasteboard.clearContents()
        guard pasteboard.writeObjects(objects) else { throw AppError(L("写入系统剪贴板失败。")) }
        return pasteboard.changeCount
    }

    func ownsGeneralPasteboard(sequence: Int) -> Bool {
        guard pasteboard.name == NSPasteboard.general.name, pasteboard.changeCount == sequence,
              SystemAccess.clipboardStatus(for: pasteboard) != .denied else { return false }
        return pasteboard.string(forType: Self.originType) == origin && pasteboard.changeCount == sequence
    }

    private func item(with formats: [(NSPasteboard.PasteboardType, Data?)]) throws -> NSPasteboardItem {
        let item = NSPasteboardItem()
        for (type, data) in formats {
            if let data, !item.setData(data, forType: type) { throw AppError(L("无法准备 %@ 格式。", type.rawValue)) }
        }
        guard item.setString(origin, forType: Self.originType) else { throw AppError(L("无法设置来源标记。")) }
        return item
    }
}
